select id, unit_price, last_value(unit_price, true) over (partition by order_id order by unit_price, id rows between unbounded preceding and current row) as last_known_unit_price, row_number() over w_grp as seq_no, row_number() over (partition by order_id order by unit_price, id) as event_seq, row_number() over (order by quantity desc, id) as seq_no_2, percent_rank() over (partition by order_id order by quantity nulls first) as quantity_percent_rank from order_items window w_grp as (order by unit_price, id)
